edits.replacement:
#root #settingsmodal #settabs{ top:calc(var(--py) + var(--sp-1)); }
/* v28.xx (cw-cardwide), his Q43 (2026-10-18): windows are "a centred card with an X in the corner that takes up NEARLY THE WHOLE screen". The earlier critic rounds (cw-setnear2, cw-setheight) shrank Settings and Keys to 720 x 720; his word is later and wins (Q7). Now the card is the screen less 48 px each side and top and bottom, the frame sits 24 px outside that, the X stays in the card corner, and the rows keep one 960 wide column in the middle so a label never sits far from its stepper. */
#root #settingsmodal, #root #keysmodal{ --cw:calc(100% - var(--sp-5) * 2); --py:var(--sp-5); }
#root #settingsmodal .tpane, #root #settingsmodal #setwrap{ max-width:calc(var(--sp-5) * 20); margin-left:auto; margin-right:auto; width:100%; box-sizing:border-box; }
#root #keysmodal #keyslist, #root #keysmodal #keysnote, #root #keysmodal .msub{ max-width:calc(var(--sp-5) * 20); margin-left:auto; margin-right:auto; width:100%; box-sizing:border-box; }
#root #keysmodal #keyslist{ max-height:calc(100vh - var(--sp-5) * 6); }

check:
{v:'VER',what:'his Q43: the Settings window is a centred card that takes up nearly the whole screen (frame within 60 px of every screen edge) with its X in the card corner',
 run:function(){
   if(!(window.__station&&window.__hubEnter)) return 'SKIP: this fixture cannot walk the Undercroft';
   var bad=[], m, b, mr, br, z, cs, fw, fh, W=window.innerWidth, H=window.innerHeight, r;
   try{
     __topClear(); __hubEnter();
     r=__station('dev','KeyE'); if(r&&r.err) return 'station: '+r.err;
     m=document.getElementById('settingsmodal'); b=document.getElementById('closesettings');
     if(!m||!b||!m.classList.contains('on')) return 'the settings window did not open';
     UIM.step(600);
     mr=m.getBoundingClientRect(); br=b.getBoundingClientRect(); z=parseFloat(m.style.zoom)||1;
     cs=getComputedStyle(m,'::before');
     fw=parseFloat(cs.width)*z; fh=parseFloat(cs.height)*z;
     if(!(fw>=W-120)) bad.push('the card frame is '+Math.round(fw)+' px wide on a '+W+' px screen, want within 120');
     if(!(fh>=H-120)) bad.push('the card frame is '+Math.round(fh)+' px tall on a '+H+' px screen, want within 120');
     if(!(mr.right-br.right<=100*z)) bad.push('the X is '+Math.round(mr.right-br.right)+' px in from the right edge');
     if(!(br.top-mr.top<=100*z)) bad.push('the X is '+Math.round(br.top-mr.top)+' px down from the top');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ __topClear(); }catch(_c){} }
   return bad.length?bad.join('; '):null; }},
